std::vector<std::vector<Point2d>> faces;

    for (auto f = arr.begin_face(); f != arr.end_face(); ++f) {
        if (arr.is_unbounded(f)) {
            continue;
        }

        std::vector<Point2d> face_points;
        auto halfedge = f->outer_halfedge();
        if (halfedge == nullptr) {
            continue;
        }

        do {
            double x, y;
            internal::getCoordinates(halfedge->source().point(), x, y);
            face_points.push_back(Point2d(x, y));
            halfedge = halfedge->next();
        } while (halfedge != f->outer_halfedge());

        faces.push_back(face_points);
    }

    return faces;

